#include <iostream>
#include <map>
#include <string>
using namespace std;

int main() {
    map<string, int> tally;
    tally["{w1}"] += 1;
    tally["{w2}"] += 1;
    tally["{w1}"] += 1;

    for (auto p : tally) {
        cout << p.first << " " << p.second << endl;
    }
    return 0;
}
